$tmp = Join-Path $env:TEMP "aura-put.txt"
function Put($k, $v) { [System.IO.File]::WriteAllText($tmp, $v, (New-Object System.Text.UTF8Encoding $false)); npx wrangler kv key put --namespace-id $ns $k --path $tmp --remote 2>$null | Out-Null }
function Bulk($keys, $rx) { $res = @{}; $kf = Join-Path $env:TEMP "aura-fix-keys.json"; for ($i = 0; $i -lt $keys.Count; $i += 100) { $chunk = @($keys[$i..([Math]::Min($i+99,$keys.Count-1))]); ConvertTo-Json $chunk | Set-Content -Path $kf -Encoding utf8; $o = (npx wrangler kv bulk get $kf --namespace-id $ns --remote 2>$null | Out-String); [regex]::Matches($o, $rx) | % { $res[$_.Groups[1].Value] = 1 } }; $res }
$tt = $null; for ($t = 1; $t -le 4 -and -not $tt; $t++) { try { $o = (npx wrangler kv key get --namespace-id $ns "card:tree" --remote 2>$null | Out-String) | ConvertFrom-Json; if ($o.subjects) { $tt = $o } } catch {}; if (-not $tt) { Start-Sleep -Seconds 5 } }
