  $last = ""
  for ($pass = 1; $pass -le 8; $pass++) {
    $m = $null; for ($try = 1; $try -le 4; $try++) { $o = (RUN ("WALK " + $c) | Out-String); $m = [regex]::Match($o, '"missing":\[(.*?)\]'); if ($m.Success) { break }; Start-Sleep -Seconds 15 }
    if (-not $m.Success) { "  NO ANSWER from WALK - run the block again"; break }
    $names = @([regex]::Matches($m.Groups[1].Value, '"([^"]+)"') | % { $_.Groups[1].Value })
    if ($names.Count -eq 0) { "  nothing missing"; break }
    $now = ($names -join "|"); if ($now -eq $last) { "  these keep failing:"; $names | % { "    " + $_ }; break }; $last = $now
    "  pass " + $pass + " - " + $names.Count + " missing"
    if ($mode[$c] -eq "REDO") { for ($i = 0; $i -lt $names.Count; $i += 5) { $r = (RUN ("REDO " + (($names[$i..([Math]::Min($i+4,$names.Count-1))]) -join ", ")) | Out-String); [regex]::Matches($r, '"([^"]+)  ->  (https://[^"]+|FAILED[^"]{0,60})"') | % { "  " + $(if ($_.Groups[2].Value -like "FAILED*") { "FAILED" } else { "ok" }) + "  " + $_.Groups[1].Value } } }
    else { foreach ($leaf in $names) { $r = (RUN ("FACE " + $leaf) | Out-String); if ($r -match '"img":"img_') { "  ok  " + $leaf } else { "  FAILED  " + $leaf } } }
  }
  RUN ("SHEET " + $c)
}
